script.setup:
// librosa analysed the loop ahead of time (recipe librosa.beat-track → beats.json): tempo, beat
// times and the onset envelope. The scene plays the audio and follows its clock, so markers can
// arrive exactly on the beat — something live analysis can't do.
const analysis = await (await fetch(ctx.assets["beats.json"])).json();
const element = await ctx.utils.audio.play("beat.wav", { loop: true });
Object.assign(ctx.state, { analysis, element, last: 0, pulse: 0, env: new Float32Array(128), beats: new Float32Array(16),
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform vec2 u_resolution; uniform float u_env[128]; uniform float u_beats[16]; uniform float u_pulse; uniform vec3 u_color; uniform float u_window;
void main(){
  vec2 p = v_uv; float aspect = u_resolution.x / u_resolution.y;
  vec3 col = vec3(0.025, 0.025, 0.04);
  // Onset envelope around now (center), librosa's analysis looked ahead of the playhead.
  float x = p.x * 127.0; int i = int(x);
  float e = mix(u_env[i], u_env[min(i + 1, 127)], fract(x));
  float lane = 0.18;
  float bar = step(p.y, lane * 0.15 + e * lane) * step(lane * 0.15 - e * lane * 0.3, p.y);
  col += u_color * bar * (p.x < 0.5 ? 0.35 : 0.8);
  // Beat markers slide toward the playhead.
  for (int k = 0; k < 16; k++) {
    float bx = 0.5 + u_beats[k] / (2.0 * u_window);
    float m = exp(-abs(p.x - bx) * u_resolution.x * 0.25) * step(p.y, lane * 1.6);
    col += vec3(1.0, 0.9, 0.7) * m * (u_beats[k] > 0.0 ? 0.9 : 0.25);
  }
  col += vec3(1.0) * exp(-abs(p.x - 0.5) * u_resolution.x * 0.5) * step(p.y, lane * 1.6) * 0.6;
  // The beat pulse.
  vec2 c = (p - vec2(0.5, 0.6)) * vec2(aspect, 1.0);
  float r = length(c);
  float ring = exp(-abs(r - (0.12 + (1.0 - u_pulse) * 0.25)) * 90.0) * u_pulse;
  col += u_color * (ring * 1.4 + smoothstep(0.12, 0.0, r) * (0.25 + 0.75 * u_pulse));
  outColor = vec4(col, 1.0);
}") });
ctx.publish("tempo", Math.round(analysis.tempo * 10) / 10);

script.render:
const s = ctx.state, a = s.analysis, u = ctx.uniforms;
const now = s.element.currentTime, D = a.duration, W = u.u_window;
// A beat crossed since the last frame (the loop wraps around).
const crossed = a.beats.some((b) => (s.last <= now ? b > s.last && b <= now : b > s.last || b <= now));
if (crossed) s.pulse = 1;
s.last = now;
s.pulse *= Math.exp(-ctx.dt * 5);
for (let i = 0; i < 128; i++) {
  const t = (((now + (i / 127 - 0.5) * 2 * W) % D) + D) % D;
  s.env[i] = a.envelope[Math.floor(t * a.envelope_fps)] ?? 0;
}
s.beats.fill(-99);
let k = 0;
for (const b of a.beats) for (const shift of [-D, 0, D]) {
  const d = b + shift - now;
  if (Math.abs(d) < W && k < 16) s.beats[k++] = d;
}
ctx.gl.useProgram(s.p);
ctx.utils.drawFullscreen(s.p, { u_env: s.env, u_beats: s.beats, u_pulse: s.pulse });
